import { cloneTemplate, createElement } from '../../utils/utils';
import { View } from '../base/Component';
class Basket extends View {
    constructor(events) {
        super(events, cloneTemplate(Basket.template));
        this._list = this.container.querySelector('.basket__list');
        this._total = this.container.querySelector('.basket__price');
        this._button = this.container.querySelector('.basket__button');
        this._button.addEventListener('click', () => {
            events.emit('order:open');
        });
        this._list.replaceChildren(createElement('p', {
            textContent: 'Корзина пуста'
        }));
        this._button.setAttribute('disabled', 'disabled');
    }
    set cards(cards) {
        if (cards.length) {
            this._list.replaceChildren(...cards);
            this._button.removeAttribute('disabled');
        }
        else {
            this._list.replaceChildren(createElement('p', {
                textContent: 'Корзина пуста'
            }));
            this._button.setAttribute('disabled', 'disabled');
        }
    }
    ;
    set total(total) {
        this.setText(this._total, `${total} синапсов`);
    }
}
Basket.template = document.querySelector('#basket');
export { Basket };
