export class AppData {
    constructor(events) {
        this.events = events;
        this.previewCard = null;
        this.basket = {
            cards: [],
        };
        this.order = {
            payment: 'online',
            email: '',
            phone: '',
            address: '',
            total: 0,
            items: []
        };
        this.formErrors = {};
    }
    setCards(cards) {
        this.items = cards;
        this.events.emit('items:change', this.items);
    }
    setPreview(card) {
        this.previewCard = card;
        this.events.emit('preview:change', this.previewCard);
    }
    inBasket(card) {
        return this.basket.cards.includes(card.id);
    }
    getBasketTotal() {
        return this.basket.cards.reduce((total, cardId) => {
            const item = this.items.find((item) => item.id === cardId);
            return total + ((item === null || item === void 0 ? void 0 : item.price) || 0);
        }, 0);
    }
    addToBasket(card) {
        this.basket.cards.push(card.id);
        this.events.emit('basket:change', this.basket);
    }
    removeFromBasket(card) {
        this.basket.cards = this.basket.cards.filter(id => id !== card.id);
        this.events.emit('basket:change', this.basket);
    }
    clearBasket() {
        this.basket.cards = [];
        this.events.emit('basket:change', this.basket);
    }
    setOrderField(field, value) {
        if (field === 'payment') {
            this.order.payment = value;
        }
        else {
            this.order[field] = value;
        }
        if (this.order.payment && this.validateOrder()) {
            this.order.total = this.getBasketTotal();
            this.order.items = this.basket.cards;
            this.events.emit('order:ready', this.order);
        }
    }
    validateOrder() {
        const errors = {};
        if (!this.order.payment) {
            errors.payment = 'Необходимо выбрать способ оплаты';
        }
        if (!this.order.email) {
            errors.email = 'Необходимо указать email';
        }
        if (!this.order.phone) {
            errors.phone = 'Необходимо указать телефон';
        }
        if (!this.order.address) {
            errors.address = 'Необходимо указать адрес';
        }
        this.formErrors = errors;
        this.events.emit('formErrors:change', this.formErrors);
        return Object.keys(errors).length === 0;
    }
}
